func (o *TaskRun) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "RunApproval":
		rel, ok := retrieved.(*Approval)
		if !ok {
			return fmt.Errorf("taskRun cannot load %T as %q", retrieved, name)
		}

		o.R.RunApproval = rel
		o.R.Loaded.RunApproval = true

		return nil
	case "RunRunArtifacts":
		rels, ok := retrieved.(RunArtifactSlice)
		if !ok {
			return fmt.Errorf("taskRun cannot load %T as %q", retrieved, name)
		}

		o.R.RunRunArtifacts = rels
		o.R.Loaded.RunRunArtifacts = true

		return nil
	case "RunRunLeases":
		rels, ok := retrieved.(RunLeaseSlice)
		if !ok {
			return fmt.Errorf("taskRun cannot load %T as %q", retrieved, name)
		}

		o.R.RunRunLeases = rels
		o.R.Loaded.RunRunLeases = true

		return nil
	case "RunRunLogs":
		rels, ok := retrieved.(RunLogSlice)
		if !ok {
			return fmt.Errorf("taskRun cannot load %T as %q", retrieved, name)
		}

		o.R.RunRunLogs = rels
		o.R.Loaded.RunRunLogs = true

		return nil
	case "Project":
		rel, ok := retrieved.(*Project)
		if !ok {
			return fmt.Errorf("taskRun cannot load %T as %q", retrieved, name)
		}

		o.R.Project = rel
		o.R.Loaded.Project = true

		return nil
	case "RequestedByUser":
		rel, ok := retrieved.(*User)
		if !ok {
			return fmt.Errorf("taskRun cannot load %T as %q", retrieved, name)
		}

		o.R.RequestedByUser = rel
		o.R.Loaded.RequestedByUser = true

		return nil
	case "TemplateTaskTemplate":
		rel, ok := retrieved.(*TaskTemplate)
		if !ok {
			return fmt.Errorf("taskRun cannot load %T as %q", retrieved, name)
		}

		o.R.TemplateTaskTemplate = rel
		o.R.Loaded.TemplateTaskTemplate = true

		return nil
	default:
		return fmt.Errorf("taskRun has no relationship %q", name)
	}
}

