// LoadRunApproval loads the taskRun's RunApproval into the .R struct
func (os TaskRunSlice) LoadRunApproval(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	approvals, err := os.RunApproval(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.RunApproval = nil
		o.R.Loaded.RunApproval = true
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range approvals {

			if !(o.ID == rel.RunID) {
				continue
			}

			o.R.RunApproval = rel
			break
		}
	}

	return nil
}

