// PreloadCount sets a count in the C struct by name
func (o *TaskRun) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "RunRunArtifacts":
		o.C.RunRunArtifacts = &count
	case "RunRunLeases":
		o.C.RunRunLeases = &count
	case "RunRunLogs":
		o.C.RunRunLogs = &count
	}
	return nil
}

type taskRunCountPreloader struct {
	RunRunArtifacts func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	RunRunLeases    func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	RunRunLogs      func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildTaskRunCountPreloader() taskRunCountPreloader {
	return taskRunCountPreloader{
		RunRunArtifacts: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*TaskRun]("RunRunArtifacts", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = TaskRuns.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(RunArtifacts.NameAsExpr()),
					sm.Where(psql.Quote(RunArtifacts.Alias(), "run_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		RunRunLeases: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*TaskRun]("RunRunLeases", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = TaskRuns.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(RunLeases.NameAsExpr()),
					sm.Where(psql.Quote(RunLeases.Alias(), "run_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		RunRunLogs: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*TaskRun]("RunRunLogs", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = TaskRuns.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(RunLogs.NameAsExpr()),
					sm.Where(psql.Quote(RunLogs.Alias(), "run_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

