type taskRunJoins[Q dialect.Joinable] struct {
	typ                  string
	RunApproval          modAs[Q, approvalColumns]
	RunRunArtifacts      modAs[Q, runArtifactColumns]
	RunRunLeases         modAs[Q, runLeaseColumns]
	RunRunLogs           modAs[Q, runLogColumns]
	Project              modAs[Q, projectColumns]
	RequestedByUser      modAs[Q, userColumns]
	TemplateTaskTemplate modAs[Q, taskTemplateColumns]
}

func (j taskRunJoins[Q]) aliasedAs(alias string) taskRunJoins[Q] {
	return buildTaskRunJoins[Q](buildTaskRunColumns(alias), j.typ)
}

func buildTaskRunJoins[Q dialect.Joinable](cols taskRunColumns, typ string) taskRunJoins[Q] {
	return taskRunJoins[Q]{
		typ: typ,
		RunApproval: modAs[Q, approvalColumns]{
			c: Approvals.Columns,
			f: func(to approvalColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Approvals.NameExpr().As(to.Alias())).On(
						to.RunID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		RunRunArtifacts: modAs[Q, runArtifactColumns]{
			c: RunArtifacts.Columns,
			f: func(to runArtifactColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RunArtifacts.NameExpr().As(to.Alias())).On(
						to.RunID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		RunRunLeases: modAs[Q, runLeaseColumns]{
			c: RunLeases.Columns,
			f: func(to runLeaseColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RunLeases.NameExpr().As(to.Alias())).On(
						to.RunID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		RunRunLogs: modAs[Q, runLogColumns]{
			c: RunLogs.Columns,
			f: func(to runLogColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RunLogs.NameExpr().As(to.Alias())).On(
						to.RunID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Project: modAs[Q, projectColumns]{
			c: Projects.Columns,
			f: func(to projectColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Projects.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.ProjectID),
					))
				}

				return mods
			},
		},
		RequestedByUser: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.RequestedBy),
					))
				}

				return mods
			},
		},
		TemplateTaskTemplate: modAs[Q, taskTemplateColumns]{
			c: TaskTemplates.Columns,
			f: func(to taskTemplateColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, TaskTemplates.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.TemplateID),
					))
				}

				return mods
			},
		},
	}
}
